import 'package:flutter/material.dart';
import '../app_state.dart';
import '../data/menu_data.dart';

class AiPage extends StatefulWidget { const AiPage({super.key}); @override State<AiPage> createState()=>_AiPageState(); }
class _AiPageState extends State<AiPage> {
 final controller=TextEditingController(); final scroll=ScrollController();
 final List<Map<String,String>> messages=[{'role':'ai','text':'Halo! Saya AI Food Assistant. 🍜\nCeritakan selera atau anggaranmu, misalnya “makanan pedas di bawah 25 ribu” atau “status pesanan”.'}];
 void sendMessage(){final q=controller.text.trim();if(q.isEmpty)return;final l=q.toLowerCase();String answer;
 if(l.contains('pesan')||l.contains('order')||l.contains('status')){final orders=AppState.instance.orders;answer=orders.isEmpty?'Kamu belum memiliki pesanan aktif. Setelah checkout, status pesanan akan muncul di halaman Pesanan.':orders.take(3).map((o)=>'Pesanan #${o.id.toString().substring(o.id.toString().length-5)} — ${o.status} (Rp${_money(o.total)})').join('\n');}
 else {final numberMatch=RegExp(r'\d+').firstMatch(l);final budget=numberMatch==null?null:(int.tryParse(numberMatch.group(0)!)??0)*1000;var found=menus.where((m){final text='${m.name} ${m.description}'.toLowerCase();final priceOk=budget==null||m.price<=budget;final preferenceOk=!(l.contains('pedas')||l.contains('spicy'))||text.contains('pedas')||text.contains('sambal')||text.contains('aceh');return priceOk&&preferenceOk;}).toList();if(found.isEmpty)found=menus.take(3).toList();answer='Ini rekomendasi yang cocok dari menu aplikasi:\n'+found.take(3).map((m)=>'• ${m.name} — Rp${_money(m.price)}\n  ${m.description}').join('\n')+'\n\nKamu bisa buka restoran dan menambahkan menu tersebut ke keranjang.';}
 setState((){messages.add({'role':'user','text':q});messages.add({'role':'ai','text':answer});controller.clear();});WidgetsBinding.instance.addPostFrameCallback((_) {if(scroll.hasClients)scroll.animateTo(scroll.position.maxScrollExtent,duration:const Duration(milliseconds:250),curve:Curves.easeOut);});}
 @override void dispose(){controller.dispose();scroll.dispose();super.dispose();}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('AI Food Assistant'),actions:[IconButton(onPressed:()=>setState(()=>messages.removeRange(1,messages.length)),icon:const Icon(Icons.refresh),tooltip:'Percakapan baru')]),body:Column(children:[Expanded(child:ListView.builder(controller:scroll,padding:const EdgeInsets.all(16),itemCount:messages.length,itemBuilder:(context,i){final m=messages[i];final mine=m['role']=='user';return Align(alignment:mine?Alignment.centerRight:Alignment.centerLeft,child:Container(constraints:const BoxConstraints(maxWidth:320),margin:const EdgeInsets.only(bottom:12),padding:const EdgeInsets.all(14),decoration:BoxDecoration(color:mine?Colors.deepOrange:Colors.white,borderRadius:BorderRadius.circular(16)),child:Text(m['text']!,style:TextStyle(color:mine?Colors.white:Colors.black87))));})),Padding(padding:const EdgeInsets.fromLTRB(12,8,12,12),child:Row(children:[Expanded(child:TextField(controller:controller,onSubmitted:(_)=>sendMessage(),decoration:InputDecoration(hintText:'Contoh: makanan pedas murah...',filled:true,fillColor:Colors.white,border:OutlineInputBorder(borderRadius:BorderRadius.circular(24),borderSide:BorderSide.none)))),const SizedBox(width:8),IconButton.filled(onPressed:sendMessage,icon:const Icon(Icons.send))]))]));
 String _money(int n)=>n.toString().replaceAllMapped(RegExp(r'\B(?=(\d{3})+(?!\d))'),(_)=>'.');
}
